/**
 * Unit tests for SimplexTableau.getSolution().
 * Since the method is protected, we use a Spy or a subclass to access it.
 */
public class SimplexTableau_getSolution_TriageGen0Test {

    private SimplexTableauSpy tableauSpy;
    private LinearObjectiveFunction mockFunction;

    // Subclass to expose protected method and allow mocking of internal state
    private static class SimplexTableauSpy extends SimplexTableau {
        public SimplexTableauSpy(double[][] data, GoalType goalType) {
            super(data, goalType);
        }

        @Override
        public RealPointValuePair getSolution() {
            return super.getSolution();
        }

        // Helper to set restrictToNonNegative via reflection if necessary, 
        // but here we assume it's accessible or we mock the behavior.
        public void setRestrictToNonNegative(boolean val) {
            try {
                Field field = SimplexTableau.class.getDeclaredField("restrictToNonNegative");
                field.setAccessible(true);
                field.set(this, val);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }

    @Before
    public void setUp() {
        // Minimal valid data for a tableau
        double[][] data = {
            {1.0, 2.0, 0.0, 10.0},
            {0.0, 0.0, 0.0, 0.0}
        };
        tableauSpy = new SimplexTableauSpy(data, GoalType.MAXIMIZE);
        mockFunction = mock(LinearObjectiveFunction.class);

        try {
            Field fField = SimplexTableau.class.getDeclaredField("f");
            fField.setAccessible(true);
            fField.set(tableauSpy, mockFunction);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testGetSolution_StandardCase() {
        // Mocking internal state via Spy to control tableau behavior
        // Rows: 0 (Obj), 1 (Constraint 1), 2 (RHS/Basic)
        // Let's simulate 2 decision variables, 1 objective
        // getOriginalNumDecisionVariables = 2
        // getNumObjectiveFunctions = 1
        // getRhsOffset = 3

        // We need to override behavior because we can't easily set the whole tableau state perfectly
        SimplexTableau spyTableau = Mockito.spy(tableauSpy);

        // Setup dimensions
        when(spyTableau.getOriginalNumDecisionVariables()).thenReturn(2);
        when(spyTableau.getNumObjectiveFunctions()).thenReturn(1);
        when(spyTableau.getRhsOffset()).thenReturn(3);
        when(spyTableau.getEntry(Mockito.anyInt(), Mockito.anyInt())).thenAnswer(invocation -> {
            int r = invocation.getArgument(0);
            int c = invocation.getArgument(1);
            if (r == 2 && c == 3) return 5.0; // mostNegative (basicRow for index 0)
            if (r == 1 && c == 3) return 10.0; // basicRow for i=0
            if (r == 2 && c == 3) return 20.0; // basicRow for i=1
            return 0.0;
        });

        // Mock basicRow indices
        // getBasicRow(numObj + originalNumVars) -> getBasicRow(3)
        // getBasicRow(numObj + i) -> getBasicRow(1+0) and getBasicRow(1+1)
        when(spyTableau.getBasicRow(3)).thenReturn(2); // mostNegative row
        when(spyTableau.getBasicRow(1)).thenReturn(1); // coefficients[0] row
        when(spyTableau.getBasicRow(2)).thenReturn(2); // coefficients[1] row

        // Mock tableau.getEntry(basicRow, j) for the loop check
        // tableau is protected, but we can mock the call if we use a spy on the tableau itself
        // However, getEntry is a method on the object.
        // Let's simulate the 'if (tableau.getEntry(basicRow, j) == 1)' condition
        // For i=1, j=1. If tableau.getEntry(2, 1) == 1, coefficients[1] = 0.
        when(spyTableau.getEntry(2, 1)).thenReturn(1.0); 

        // Mock function value
        when(mockFunction.getValue(Mockito.any(double[].class))).thenReturn(50.0);

        RealPointValuePair result = spyTableau.getSolution();

        // Calculation:
        // mostNegative = getEntry(2, 3) = 20 (Wait, logic: basicRow for index 0 is 2, getEntry(2,3) is 20)
        // i=0: basicRow = getBasicRow(1) = 1. coeff[0] = getEntry(1,3) - 0 = 10.
        // i=1: basicRow = getBasicRow(2) = 2. coeff[1] = getEntry(2,3) - 0 = 20.
        // But loop j: for i=1, j=1. tableau.getEntry(2, 1) is 1.0, so coeff[1] = 0.

        assertArrayEquals(new double[]{10.0, 0.0}, result.getPoint(), 1e-9);
        assertEquals(50.0, result.getValue(), 1e-9);
    }

    @Test
    public void testGetSolution_WithRestrictToNonNegativeTrue() {
        SimplexTableauSpy spyTableau = new SimplexTableauSpy(new double[][]{{0}}, GoalType.MAXIMIZE);
        spyTableau.setRestrictToNonNegative(true);

        SimplexTableau wrappedSpy = Mockito.spy(spyTableau);
        when(wrappedSpy.getOriginalNumDecisionVariables()).thenReturn(1);
        when(wrappedSpy.getNumObjectiveFunctions()).thenReturn(1);
        when(wrappedSpy.getRhsOffset()).thenReturn(1);

        // mostNegative row
        when(wrappedSpy.getBasicRow(2)).thenReturn(1);
        when(wrappedSpy.getEntry(1, 1)).thenReturn(-5.0); // mostNegative = -5

        // i=0 row
        when(wrappedSpy.getBasicRow(1)).thenReturn(2);
        when(wrappedSpy.getEntry(2, 1)).thenReturn(10.0);

        // restrictToNonNegative is true, so coeff = 10.0 - 0 = 10.0
        when(mockFunction.getValue(Mockito.any(double[].class))).thenReturn(100.0);

        RealPointValuePair result = wrappedSpy.getSolution();
        assertArrayEquals(new double[]{10.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_WithRestrictToNonNegativeFalse() {
        SimplexTableauSpy spyTableau = new SimplexTableauSpy(new double[][]{{0}}, GoalType.MAXIMIZE);
        spyTableau.setRestrictToNonNegative(false);

        SimplexTableau wrappedSpy = Mockito.spy(spyTableau);
        when(wrappedSpy.getOriginalNumDecisionVariables()).thenReturn(1);
        when(wrappedSpy.getNumObjectiveFunctions()).thenReturn(1);
        when(wrappedSpy.getRhsOffset()).thenReturn(1);

        // mostNegative row
        when(wrappedSpy.getBasicRow(2)).thenReturn(1);
        when(wrappedSpy.getEntry(1, 1)).thenReturn(-5.0); // mostNegative = -5

        // i=0 row
        when(wrappedSpy.getBasicRow(1)).thenReturn(2);
        when(wrappedSpy.getEntry(2, 1)).thenReturn(10.0);

        // restrictToNonNegative is false, so coeff = 10.0 - (-5.0) = 15.0
        when(mockFunction.getValue(Mockito.any(double[].class))).thenReturn(150.0);

        RealPointValuePair result = wrappedSpy.getSolution();
        assertArrayEquals(new double[]{15.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_NullBasicRows() {
        SimplexTableau spyTableau = Mockito.spy(tableauSpy);
        when(spyTableau.getOriginalNumDecisionVariables()).thenReturn(1);
        when(spyTableau.getNumObjectiveFunctions()).thenReturn(1);
        when(spyTableau.getRhsOffset()).thenReturn(1);

        // mostNegative row is null
        when(spyTableau.getBasicRow(2)).thenReturn(null);
        // coefficients[0] row is null
        when(spyTableau.getBasicRow(1)).thenReturn(null);

        when(mockFunction.getValue(Mockito.any(double[].class))).thenReturn(0.0);

        RealPointValuePair result = spyTableau.getSolution();
        assertArrayEquals(new double[]{0.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_WithCoefficientResetToZero() {
        SimplexTableau spyTableau = Mockito.spy(tableauSpy);
        when(spyTableau.getOriginalNumDecisionVariables()).thenReturn(2);
        when(spyTableau.getNumObjectiveFunctions()).thenReturn(1);
        when(spyTableau.getRhsOffset()).thenReturn(3);

        when(spyTableau.getBasicRow(3)).thenReturn(null); // mostNegative = 0

        // i=0
        when(spyTableau.getBasicRow(1)).thenReturn(1);
        when(spyTableau.getEntry(1, 3)).thenReturn(5.0);

        // i=1
        when(spyTableau.getBasicRow(2)).thenReturn(2);
        when(spyTableau.getEntry(2, 3)).thenReturn(10.0);
        // Trigger the zeroing logic: for i=1, j=1. If tableau.getEntry(2, 1) == 1
        when(spyTableau.getEntry(2, 1)).thenReturn(1.0);

        when(mockFunction.getValue(Mockito.any(double[].class))).thenReturn(5.0);

        RealPointValuePair result = spyTableau.getSolution();
        // i=0 -> 5.0
        // i=1 -> 0.0 (because entry(2,1) == 1)
        assertArrayEquals(new double[]{5.0, 0.0}, result.getPoint(), 1e-9);
    }
}
